// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DEP_BANK} from "../src/DEP_BANK.sol";

contract InvMutTest is Test {
    DEP_BANK c;
    function setUp() public { c = new DEP_BANK(); }

    function testFuzz_property(uint256 depositAmount, uint256 collectAmount, uint256 minSum) public {
        // Setup a valid LogFile so that Collect/Deposit don't revert on the external call.
        LogFile log = new LogFile();
        c.SetLogFile(address(log));

        // Wide but bounded domain.
        depositAmount = bound(depositAmount, 1, type(uint128).max);
        collectAmount = bound(collectAmount, 0, depositAmount);
        minSum = bound(minSum, 0, depositAmount);

        // Make the condition balances >= MinSum && balances >= _am true under the reference,
        // and exactly equal to MinSum for some inputs so that the mutant (strict >) is
        // guaranteed to be distinguishable.
        c.SetMinSum(minSum);

        address actor = address(0xA11CE);
        vm.deal(actor, depositAmount);

        // Deposit so that balances[actor] == depositAmount.
        vm.prank(actor);
        c.Deposit{value: depositAmount}();

        uint256 beforeBal = c.balances(actor);

        // Call Collect with exactly collectAmount; under the reference this should succeed
        // when beforeBal >= MinSum && beforeBal >= collectAmount.
        bool ok = true;
        vm.prank(actor);
        try c.Collect(collectAmount) { ok = true; } catch { ok = false; }

        uint256 afterBal = c.balances(actor);

        // General rule: if the caller has at least MinSum and enough balance for _am, then
        // Collect must succeed and reduce the caller's balance by exactly _am.
        // This holds for the reference C. The mutant uses balances > MinSum, so when
        // beforeBal == MinSum (or when the condition equals exactly), it skips the state
        // change, breaking this rule.
        if (beforeBal >= c.MinSum() && beforeBal >= collectAmount) {
            assertTrue(ok && afterBal == beforeBal - collectAmount);
        } else {
            assertTrue(!ok && afterBal == beforeBal);
        }
    }
}

contract LogFile {
    struct Message { address Sender; string Data; uint Val; uint Time; }
    Message[] public History;
    Message LastMsg;
    function AddMessage(address _adr, uint _val, string memory _data) public {
        LastMsg.Sender = _adr;
        LastMsg.Time = block.timestamp;
        LastMsg.Val = _val;
        LastMsg.Data = _data;
        History.push(LastMsg);
    }
}
